<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Contact | DreamNest</title><link rel="stylesheet" href="css/style.css"></head><body><?php include 'includes/header.php'; ?><?php require 'includes/config.php';$msg='';
