<section class="pagehero"><div class="container"><h1>Contact Us</h1><p>Send an enquiry to our property team.</p></div></section><section class="section"><div class="container grid2"><form class="form-card" method="post"><h2 style="color:var(--navy)">Send an Enquiry</h2><?php if($msg):?><p class="message"><?=$msg?></p><?php endif;?><input type="hidden" name="property_id" value="<?=$pid?>"><br><div class="formgrid"><div><label>Name</label><input name="name" required></div><div><label>Email</label><input name="email" type="email" required></div><div><label>Phone</label><input name="phone"></div><div><label>Subject</label><input name="subject" value="<?=htmlspecialchars($ptitle?'Interest in '.$ptitle:'General Enquiry')?>"></div><div class="full"><label>Message</label><textarea name="message" rows="6" required><?=htmlspecialchars($ptitle?'I am interested in '.$ptitle.'.':'')?></textarea></div><div class="full"><button class="btn gold">Send Enquiry</button></div></div></form><div><h2 style="color:var(--navy);font-size:36px">Let's talk property.</h2><div class="category" style="text-align:left;margin-top:20px"><h3>DreamNest Office</h3><p>📍 Ahmedabad, Gujarat, India</p><p>☎ +91 98765 43210</p><p>✉ info@dreamnest.com</p></div></div></div></section><?php include 'includes/footer.php'; ?></body></html>